mapper.select:
SELECT

FROM t_task t
INNER JOIN t_wx_member c ON c.member_id = t.creator_id


    t.deleted_flag = 0

        AND (
            t.title LIKE CONCAT('%', #{query.searchWord}, '%')
            OR c.nickname LIKE CONCAT('%', #{query.searchWord}, '%')
            OR CAST(t.task_id AS CHAR) = #{query.searchWord}
        )


        AND t.status = #{query.status}


        AND t.creator_id = #{query.creatorId}


        AND t.status IN (1, 2) AND t.deadline < NOW()


        AND NOT (t.status IN (1, 2) AND t.deadline < NOW())


        AND t.create_time >= #{query.beginDate}


        AND t.create_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)



    ORDER BY t.task_id DESC
